 // ReviewDraftFinding is one finding a draft reports.
 type ReviewDraftFinding struct {
 	ID          string `json:"id"`
 	Severity    string `json:"severity"`
 	Disposition string `json:"disposition"`
 	File        string `json:"file,omitempty"`
 	Line        int    `json:"line,omitempty"`
 	Summary     string `json:"summary"`
 	// Action, Owner and ReviewBy let a follow-up become an accepted risk in
 	// the attestation the engine records (spec
 	// pose-delegated-review-conclusions R1).
 	Action   string `json:"action,omitempty"`
 	Owner    string `json:"owner,omitempty"`
 	ReviewBy string `json:"review_by,omitempty"`
+	// Limit names the declared accepted limit the finding falls inside
+	// (spec pose-review-declared-threat-model R2).
+	Limit string `json:"limit,omitempty"`
 }

 // ReviewDraftCriterion answers one criterion of the plan, as the reviewer of
 // a recorded attestation does (spec pose-delegated-review-conclusions R1).
 type ReviewDraftCriterion struct {
 	ID          string `json:"id"`
 	Disposition string `json:"disposition"`
 	Evidence    string `json:"evidence,omitempty"`
 	Rationale   string `json:"rationale,omitempty"`
 	// Mappings answer the structural facts the criterion is responsible for,
 	// as `--criterion` mappings do; the writer's gate judges them (review
 	// round 1, B4).
 	Mappings []ReviewCriterionMapping `json:"mappings,omitempty"`
 }

 // ReviewDraftTool is the disposition of one tool the plan requires.
 type ReviewDraftTool struct {
 	ID          string `json:"id"`
 	Component   string `json:"component,omitempty"`
 	Disposition string `json:"disposition"`
 	Evidence    string `json:"evidence,omitempty"`
 	Rationale   string `json:"rationale,omitempty"`
 }

 // ReviewDraftPrior is a draft's account of one prior finding (R3, R4).
 type ReviewDraftPrior struct {
 	ID       string `json:"id"`
 	Status   string `json:"status"`
 	Evidence string `json:"evidence"`
 }

 // ReviewDraft is the pose-draft block of a reviewer's final message.
 type ReviewDraft struct {
 	Schema        string               `json:"schema"`
 	Decision      string               `json:"decision"`
 	Findings      []ReviewDraftFinding `json:"findings"`
 	PriorFindings []ReviewDraftPrior   `json:"prior_findings,omitempty"`
 	Sweep         string               `json:"sweep,omitempty"`
 	// Criteria and Tools are the typed conclusion the engine records as an
 	// attestation (spec pose-delegated-review-conclusions R1).
 	Criteria []ReviewDraftCriterion `json:"criteria,omitempty"`
 	Tools    []ReviewDraftTool      `json:"tools,omitempty"`
 	// Questions and Surfaces are the typed verdict of an adjudication and of
 	// a smoke run, recorded where their origin reads them (spec
 	// pose-delegated-verdict-destinations R1, R2).
 	Questions []ReviewDraftQuestion `json:"questions,omitempty"`
 	Surfaces  []ReviewDraftSurface  `json:"surfaces,omitempty"`
 	// BusinessDecision is a question the reviewer cannot answer from the
 	// code, for a person to decide (spec
 	// pose-delegated-review-action-fulfillment R7).
 	BusinessDecision *ReviewDraftBusinessDecision `json:"business_decision,omitempty"`
 }

 // ReviewDraftBusinessDecision is a business question and its options.
 type ReviewDraftBusinessDecision struct {
 	Question string         `json:"question"`
 	Options  []ActionOption `json:"options"`
 }

